import json
from pathlib import Path
P=Path(__file__).resolve().parent
rs=json.loads((P/'remaining-initial.json').read_text());done={x['Form_ID'] for f in P.glob('pass*-saved-assignments.json') for x in json.loads(f.read_text())}
groups=[
 dict(parent='11418-4',gloss=['bark'],forms=['bokarā','bokrā','bokri','bokoro','bokalā'],citation='CDIAL[11418,3]',evidence='In the third section Turner separates *valkhala and *vōlkala, placing Nepali bokro and Hindi boklā after the o-vowel branch. These northern survey bokr-/bokl- bark forms match that specific *vōlkala formation and ordinary final vowel variation. Aspirated or retroflex-extended responses are left unresolved rather than combined with the a-vowel valkala branch.'),
 dict(parent='11418',gloss=['bark'],forms=['bakala'],citation='CDIAL[11418,1]',evidence='Turner gives Prakrit vakkala and Hindi bakal/bakkal/baklā bark under valkala, with parallel Oriya bakaḷa and Assamese bakalā. Kathoriya bakala matches this a-vowel branch; o-vowel bokrā forms are assigned separately to *vōlkala.'),
 dict(parent='9882',gloss=['monkey'],languages=['RathwiBareli','Bhilali','Bhili','PalyaBareli','PauriBareli'],forms=['makaḍīū','mākaḍīyū','mākaḍīyā','mākaṛyū','mākhaḍyo','makaḍīyo','mākaḍīyo','mākaḍyā','mākaḍiyā','makaḍiya','makaḍīo','mākaḍiu','mākaḍio'],citation='CDIAL[9882]',evidence='Turner’s markáṭa monkey article explicitly includes Marathi mākaḍ, Gujarati mākṛũ/mā̃kṛũ and Prakrit makkaḍa/makkaḍī, with probable older Dravidian ancestry. These western survey forms retain the diagnostic māk-ḍ/ṛ sequence and regional final i/y-vowels; sporadic aspiration is preserved as a source variant. The separate mārkaṭa article 10069 has monkey-like/lean/reddish senses and is not the selected noun parent.'),
 dict(parent='3275',gloss=['dog'],forms=['kūṭṭā','kutʰa','kūtʰa','kūṭṭo','kuṭā','koṭṭā','ˈkōt̪ə','kōt̪ə','kōt̪a'],citation='CDIAL[3275]',evidence='Turner’s onomatopoeic *kutta family includes Punjabi/Lahnda kuttā, West Pahari kuttā, Nepali kuti, Oriya kutā, Hindi kuttā and Gujarati kuttɔ. These whole survey dog forms fit that regional family, retaining the source’s dental/retroflex and occasional aspirated spellings as expressive variation rather than a claimed regular sound law. r-bearing and doubly aspirated responses are excluded.'),
 dict(parent='12528',gloss=['dog'],languages=['Gaw','Noiri','Vasavi'],forms=['śūna','hūṇɔ','hū̃ṇo','huṇo'],citation='CDIAL[12528,1]',evidence='Turner explicitly lists Gawri šūnā and Marathi suṇẽ under the first śuna branch, contrasting the feminine śunī and aspirated śunakha branches. Gawri śūna and the western Bhil masculine hūṇo forms fit that whole stem, with the western s-to-h correspondence retained. Feminine-looking huṇi and Kullu śoṇ are left unassigned because subsection choice is less secure.'),
 dict(parent='13544-2',gloss=['pig'],languages=['KochariyaEastDanuwar','KochilaTharu'],forms=['sʰugur','sugar'],citation='CDIAL[13544,2]',evidence='The second *sūṅkara subsection explicitly lists Nepali sũgar/sũgur, Kumaoni sũgar and Jaunsari sũgar, with Koci suṅgur in the addendum. The survey sugar/sugur forms retain g like that regional branch, unlike the ordinary sūkara > suar series; absent nasal marking and source aspiration notation remain visible.'),
 dict(parent='3208',gloss=['chicken'],forms=['kīkīr','kīkīr / kūkūr','kū̃kū̃ / kū̃kvī','kūko / kūkūī̃','kū̃kū̃ / kūkvī','kūkvī̃ / kū̃kū̃','kūkū̃','kūkū̃ / kūkvī','kukʰri','kukʰudā','kʰukri','kukʰurā','kukʰrā','kovkṛa','kakṛa','kukovṛa','kūkɨḍa','kūkɨra','kukhaṛi','kukəḷũ','kukəḷi','kukəṛə','kukʰṛi','kukuḍi','kukṛe','kūkiḍi'],citation='CDIAL[3208]',evidence='Turner’s onomatopoeic kukkuṭa family explicitly includes Bashkarik kukur/kikir, Maiya koko, Shina koko/kukūĩ, Oriya kukuṛā, Gujarati kukṛɔ/kukṛī, and Nepali kukhro with expressive aspiration; the addendum gives Kullu-area kukhṛɔ/kukhṛī. These whole male/female or single-stem survey responses fit that documented family. Both members of each included slash response are accounted for; unrelated kakavãk and murga responses are excluded.'),
]
a=[]
for i,g in enumerate(groups):
 for r in rs:
  if r['ID'] not in done and r['Gloss'] in g['gloss'] and r['Form'] in g['forms'] and ('languages' not in g or r['Language_ID'] in g['languages']):a.append(dict(record=r,parent=g['parent'],kind='reflex',citation=g['citation'],evidence=g['evidence'],family=i))
assert len(a)==len({x['record']['ID'] for x in a})
(P/'pass023-decisions.json').write_text(json.dumps(dict(accepted=a,held=[]),ensure_ascii=False,indent=1)+'\n')
(P/'pass023-rules.json').write_text(json.dumps(groups,ensure_ascii=False,indent=1)+'\n')
print(len(a),[(g['parent'],sum(x['family']==i for x in a)) for i,g in enumerate(groups)])
